// Helper to switch to mock mode
export function enableMockMode() {
  if (hasRealSupabase) return; // Never downgrade if real database credentials are present
  if (!useMock) {
    useMock = true;
    localStorage.setItem(USE_MOCK_SUPABASE_KEY, 'true');
    window.dispatchEvent(new Event('supabase_mock_mode_enabled'));
  }
}

// Check if mock mode is active
export function isMockMode() {
  return useMock;
}

// Check if we should disable mock mode (e.g. if explicitly cleared)
export function disableMockMode() {
  useMock = false;
  localStorage.removeItem(USE_MOCK_SUPABASE_KEY);
  localStorage.removeItem(MOCK_SESSION_KEY);
  window.dispatchEvent(new Event('supabase_mock_mode_disabled'));
}

// Check if current error is a network connectivity error
function isNetworkError(err: any): boolean {
  if (!err) return false;
  const msg = String(err.message || err).toLowerCase();
  return (
    msg.includes('failed to fetch') ||
    msg.includes('network error') ||
    msg.includes('load failed') ||
    msg.includes('dns') ||
    msg.includes('connection') ||
    msg.includes('unreachable') ||
    msg.includes('cors')
  );
}

