// Mock Supabase Client Object
const mockSupabase = {
  auth: {
    onAuthStateChange(callback: any) {
      mockAuthListeners.push(callback);
      const session = getMockSession();
      setTimeout(() => {
        callback(session ? 'SIGNED_IN' : 'SIGNED_OUT', session);
      }, 0);
      return {
        data: {
          subscription: {
            unsubscribe() {
              mockAuthListeners = mockAuthListeners.filter(l => l !== callback);
            }
          }
        }
      };
    },
    async getSession() {
      return { data: { session: getMockSession() }, error: null };
    },
    async signInWithPassword({ email, password }: any) {
      if (!email.includes('@')) {
        return { data: { session: null, user: null }, error: new Error('Invalid email format') };
      }
      if (password.length < 6) {
        return { data: { session: null, user: null }, error: new Error('Password must be at least 6 characters') };
      }
      
      const users = getMockUsers();
      let user = users.find(u => u.email === email);
      if (!user) {
        // If email matches one of the seeded users but isn't registered, create it
        if (email === 'admin@hiremate.ai') {
          user = createMockUser('admin@hiremate.ai', 'Administrator');
        } else if (email === 'recruiter@hiremate.ai') {
          user = createMockUser('recruiter@hiremate.ai', 'Jane Recruiter');
        } else {
          // Allow automatic signup for any emails to make local dev super easy
          user = createMockUser(email, email.split('@')[0]);
        }
      }
      
      setMockSession(user);
      triggerAuthChange('SIGNED_IN', getMockSession());
      return { data: { session: getMockSession(), user }, error: null };
    },
    async signUp({ email, password, options }: any) {
      if (password.length < 6) {
        return { data: { session: null, user: null }, error: new Error('Password must be at least 6 characters') };
      }
      const users = getMockUsers();
      if (users.some(u => u.email === email)) {
        return { data: { session: null, user: null }, error: new Error('User already registered') };
      }
      
      const fullName = options?.data?.full_name || email.split('@')[0];
      const user = createMockUser(email, fullName);
      setMockSession(user);
      triggerAuthChange('SIGNED_IN', getMockSession());
      return { data: { session: getMockSession(), user }, error: null };
    },
    async signOut() {
      clearMockSession();
      triggerAuthChange('SIGNED_OUT', null);
      return { error: null };
    }
  },
  functions: {
    async invoke(functionName: string, options?: any) {
      if (functionName === 'delete-user') {
        const userId = options?.body?.userId;
        if (!userId) return { data: null, error: new Error('User ID required') };

        const adminUser = getMockUsers().find((u: any) => u.email === 'admin@hiremate.ai');
        if (adminUser && userId === adminUser.id) {
          return { data: null, error: new Error('Action prohibited: Root HireSort platform admin account cannot be deleted.') };
        }

        let profiles = getMockProfiles().filter(p => p.id !== userId);
        saveMockProfiles(profiles);

        let roles = getMockRoles().filter(r => r.user_id !== userId);
        saveMockRoles(roles);

        let users = getMockUsers().filter(u => u.id !== userId);
        saveMockUsers(users);

        return { data: { success: true }, error: null };
      }
      if (functionName === 'invite-user') {
        const { email, role, clientId } = options?.body || {};
        if (!email) return { data: null, error: new Error('Email required') };
        
        const existing = getMockUsers().find(u => u.email === email);
        if (existing) return { data: null, error: new Error('User already exists') };
        
        const user = createMockUser(email, email.split('@')[0], role);
        let roles = getMockRoles().map(r => r.user_id === user.id ? { ...r, role: role || 'recruiter', client_id: clientId || null } : r);
        saveMockRoles(roles);
        
        return { data: { success: true }, error: null };
      }
      return { data: { success: true }, error: null };
    }
  },
  from(table: string) {
    return new MockQueryBuilder(table);
  }
};

// Helper to wrap real database query builder chain
function wrapQueryBuilder(queryBuilder: any, table: string): any {
  return new Proxy(queryBuilder, {
    get(target: any, prop: string): any {
      const val = target[prop];
      if (typeof val === 'function') {
        return (...args: any[]) => {
          const res = val.apply(target, args);
          if (res && (typeof res === 'object' || typeof res === 'function')) {
            return wrapQueryBuilder(res, table);
          }
          return res;
        };
      }
      if (prop === 'then') {
        return (onfulfilled: any, onrejected: any) => {
          return target.then(
            (val: any) => {
              if (val && val.error && isNetworkError(val.error)) {
                console.warn(`Supabase query network error on ${table}, switching to mock mode.`, val.error);
                enableMockMode();
                return mockSupabase.from(table).execute().then(onfulfilled, onrejected);
              }
              return onfulfilled ? onfulfilled(val) : val;
            },
            (err: any) => {
              if (isNetworkError(err)) {
                console.warn(`Supabase query exception on ${table}, switching to mock mode.`, err);
                enableMockMode();
                return mockSupabase.from(table).execute().then(onfulfilled, onrejected);
              }
              return onrejected ? onrejected(err) : Promise.reject(err);
            }
          );
        };
      }
      return val;
    }
  });
}

// Proxied supabase client
export const supabase = new Proxy(realSupabase, {
  get(target: any, prop: string): any {
    if (useMock) {
      return (mockSupabase as any)[prop];
    }
    
    if (prop === 'auth') {
      return authProxy;
    }
    
    if (prop === 'from') {
      return (table: string) => {
        if (useMock) {
          return mockSupabase.from(table);
        }
        return wrapQueryBuilder(realSupabase.from(table), table);
      };
    }
    
    const val = target[prop];
    if (typeof val === 'function') {
      return (...args: any[]) => {
        try {
          const res = val.apply(target, args);
          if (res instanceof Promise) {
            return res.then((resolvedVal: any) => {
              if (resolvedVal && resolvedVal.error && isNetworkError(resolvedVal.error)) {
                console.warn("Supabase network error in response, switching to mock mode.", resolvedVal.error);
                enableMockMode();
                return (mockSupabase as any)[prop](...args);
              }
              return resolvedVal;
            }).catch((err) => {
              if (isNetworkError(err)) {
                console.warn("Supabase network error exception, switching to mock mode.", err);
                enableMockMode();
                return (mockSupabase as any)[prop](...args);
              }
              throw err;
            });
          }
          return res;
        } catch (err) {
          if (isNetworkError(err)) {
            console.warn("Supabase network error caught, switching to mock mode.", err);
            enableMockMode();
            return (mockSupabase as any)[prop](...args);
          }
          throw err;
        }
      };
    }
    return val;
  }
});

